<?php
namespace Tests\Feature;
use Illuminate\Database\Schema\Blueprint;use Illuminate\Support\Facades\Schema;use Tests\TestCase;
class SecurityModuleTest extends TestCase{
 protected function setUp():void{parent::setUp();Schema::create('roles',function(Blueprint$t){$t->id();$t->string('name')->unique();$t->boolean('is_active')->default(true);$t->boolean('is_system')->default(false);$t->timestamps();});Schema::create('users',function(Blueprint$t){$t->id();$t->unsignedBigInteger('role_id')->nullable();$t->string('username')->unique();$t->string('name');$t->string('first_name')->nullable();$t->string('last_name')->nullable();$t->string('email')->unique();$t->string('password');$t->boolean('is_active')->default(true);$t->timestamp('last_login_at')->nullable();$t->rememberToken();$t->timestamps();});}
 protected function tearDown():void{Schema::dropIfExists('users');Schema::dropIfExists('roles');parent::tearDown();}
 public function test_role_buttons_backend_and_user_edit_flow():void{$role=$this->postJson('/api/security/roles',['name'=>'Supervisor','is_active'=>1])->assertCreated()->json();$this->postJson('/api/security/roles',['name'=>'Supervisor','is_active'=>1])->assertUnprocessable();$user=$this->postJson('/api/security/users',['username'=>'supervisor','password'=>'ERP123','password_confirmation'=>'ERP123','first_name'=>'Ana','last_name'=>'Pérez','email'=>'ana@example.com','role_id'=>$role['id'],'is_active'=>1])->assertCreated()->json();$this->getJson('/api/security/users/'.$user['id'])->assertOk()->assertJsonPath('username','supervisor');$this->deleteJson('/api/security/roles/'.$role['id'])->assertUnprocessable();$this->putJson('/api/security/users/'.$user['id'],['username'=>'supervisor-editado','first_name'=>'Ana','last_name'=>'Pérez','email'=>'ana@example.com','role_id'=>$role['id'],'is_active'=>1])->assertOk()->assertJsonPath('username','supervisor-editado');}
}
